	private TupleExpr root(Position position, boolean externalRead) {
		ValueFactory vf = repository.getValueFactory();
		MapBindingSet defined = new MapBindingSet();
		defined.addBinding("c", vf.createLiteral("1", XSD.INTEGER));
		defined.addBinding("u", vf.createLiteral("1", XSD.INTEGER));
		MapBindingSet undefined = new MapBindingSet();
		undefined.addBinding("c", vf.createLiteral("1", XSD.INTEGER));
		BindingSetAssignment values = new BindingSetAssignment();
		values.setBindingNames(Set.of("c", "u"));
		values.setBindingSets(List.of(defined, copy(defined), undefined));
		assertThat(values.getAssuredBindingNames()).contains("c").doesNotContain("u");
		Distinct boundary = new Distinct(values);
		assertThat(TupleExprs.isVariableScopeChange(boundary)).isFalse();
		TupleExpr q = pattern("q", "n");
		TupleExpr p = pattern("p", "o");
		TupleExpr left = position == Position.LEADING ? new Join(boundary, q) : new Join(q, boundary);
		if (externalRead && position == Position.LEADING) {
			left = condition(left, "n");
		}
		TupleExpr body = new Join(left, p);
		if (externalRead && position == Position.INTERIOR) {
			body = condition(body, "o");
		}
		TupleExpr root = project(body, List.of("s", "n", "o", "c", "u"));
		new FilterOptimizer().optimize(root, null, EmptyBindingSet.getInstance());
		List<Filter> filters = new ArrayList<>();
		root.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Filter filter) {
				filters.add(filter);
				super.meet(filter);
			}
		});
		assertThat(filters).hasSize(externalRead ? 1 : 0);
		if (externalRead) {
			Filter filter = filters.get(0);
			assertThat(filter.getRequiredInputBindingNames()).contains("c");
			assertThat(filter.getArg().getBindingNames()).doesNotContain("c");
			assertThat(LmdbNativeAggregatePlannerBase.enclosingAssuredBindingNames(filter)).contains("c");
		}
		return root;
	}

	private static Filter condition(TupleExpr input, String local) {
		return new Filter(input, new Compare(new Bound(new Var(local)), new Bound(new Var("c")),
				Compare.CompareOp.EQ));
	}

	private List<BindingSet> hand() {
		List<BindingSet> result = new ArrayList<>();
		ValueFactory vf = repository.getValueFactory();
		for (int index = 1; index <= 2; index++) {
			for (boolean defined : List.of(true, false)) {
				MapBindingSet binding = new MapBindingSet();
				binding.addBinding("s", vf.createIRI(EX, "s" + index));
				binding.addBinding("n", vf.createLiteral(index));
				binding.addBinding("o", vf.createLiteral(index == 1 ? "alpha" : "bravo"));
				binding.addBinding("c", vf.createLiteral("1", XSD.INTEGER));
				if (defined) {
					binding.addBinding("u", vf.createLiteral("1", XSD.INTEGER));
				}
				result.add(binding);
			}
		}
		return result;
	}

	private static void genericLeaves(SlotPlan plan, List<GenericEvalPlan> found) {
		if (plan instanceof GenericEvalPlan generic) {
			found.add(generic);
		} else if (plan instanceof JoinPlan join) {
			genericLeaves(join.left, found);
			genericLeaves(join.right, found);
		} else if (plan instanceof FilterPlan filter) {
			genericLeaves(filter.arg, found);
		}
	}

	private static long slotMask(NativeRowsStep step, String name) {
		for (int index = 0; index < step.layout.slotNames().length; index++) {
			if (step.layout.slotNames()[index].equals(name)) {
				return 1L << index;
			}
		}
		throw new AssertionError("missing actual compiled slot: " + name);
	}

	private static long filterReads(SlotPlan plan) {
		if (plan instanceof FilterPlan filter) {
			assertThat(filter.filterMask).isNotNegative();
			return filter.filterMask | filterReads(filter.arg);
		}
		if (plan instanceof MultiJoinPlan multi) {
			long reads = 0L;
			for (MaskedFilter filter : multi.filters) {
				assertThat(filter.mask).isNotNegative();
				reads |= filter.mask;
			}
			return reads;
		}
		if (plan instanceof JoinPlan join) {
			return filterReads(join.left) | filterReads(join.right);
		}
		return 0L;
	}

	private StatementPattern pattern(String predicate, String name) {
		return new StatementPattern(new Var("s"),
				new Var("_" + predicate, repository.getValueFactory().createIRI(EX, predicate)), new Var(name));
	}

	private static TupleExpr project(TupleExpr body, List<String> names) {
		ProjectionElemList elements = new ProjectionElemList();
		for (String name : names) {
			elements.addElement(new ProjectionElem(name));
		}
		Projection root = new Projection(body, elements, false);
		root.setRuntimeTelemetryEnabled(true);
		return root;
	}

	private static MapBindingSet copy(BindingSet input) {
		MapBindingSet result = new MapBindingSet();
		for (Binding binding : input) {
			result.addBinding(binding.getName(), binding.getValue());
		}
		return result;
	}

	private static void patterns(SlotPlan plan, List<SlotPlan> patterns) {
		if (plan instanceof JoinPlan join) {
			patterns(join.left, patterns);
			patterns(join.right, patterns);
		} else if (plan instanceof MultiJoinPlan multi) {
			for (SlotPlan child : multi.children) {
				patterns(child, patterns);
			}
		} else if (plan instanceof FilterPlan filter) {
			patterns(filter.arg, patterns);
		} else if (plan instanceof PatternPlan) {
			patterns.add(plan);
		}
	}

	private List<BindingSet> originalRows(NativeRowsStep step, RowState row, SlotPlan original, boolean ordered)
			throws IOException {
		assertThat(LmdbNativeInteriorPlans.hasAlternatives(original)).isFalse();
		assertThat(row.encounterOrderRequired).isFalse();
		long before = step.originalExpr.getLongMetricActual(OPTIMIZED);
		List<BindingSet> result;
		try (RowCursor cursor = ordered ? LmdbNativeFactorAlgebra.openOrdered(original, row) : original.open(row)) {
			assertThat(row.encounterOrderRequired).isFalse();
			result = read(step, row, cursor);
		}
		assertThat(row.encounterOrderRequired).isFalse();
		assertThat(step.originalExpr.getLongMetricActual(OPTIMIZED)).isEqualTo(before);
		return result;
	}

	private List<BindingSet> drainSelected(NativeRowsStep step, RowState row,
			LmdbNativeInteriorPlans.Selection selected, boolean ordered) throws IOException {
		SlotPlan consumer = new SlotPlan() {
			@Override
			public RowCursor open(RowState input) throws IOException {
				assertThat(input.encounterOrderRequired).isEqualTo(ordered);
				LmdbNativeInteriorPlans.Selection qualified = selected.requiresLexical(input)
						? LmdbNativeInteriorPlans.select(selected.original, input, null)
						: selected;
				assertThat(qualified.requiresLexical(input)).isFalse();
				RowCursor delegate = qualified.open(input, qualified.plan);
				return new RowCursor() {
					@Override
					public boolean next() throws IOException {
						assertThat(input.encounterOrderRequired).isEqualTo(ordered);
						boolean next = delegate.next();
						assertThat(input.encounterOrderRequired).isEqualTo(ordered);
						return next;
					}

					@Override
					public void close() {
						boolean before = input.encounterOrderRequired;
						try {
							delegate.close();
						} finally {
							assertThat(before).isEqualTo(ordered);
							assertThat(input.encounterOrderRequired).isEqualTo(ordered);
						}
					}
				};
			}

			@Override
			public long producedMask() {
				return selected.plan.producedMask();
			}
		};
		assertThat(row.encounterOrderRequired).isFalse();
		List<BindingSet> result;
		try (RowCursor cursor = ordered ? LmdbNativeFactorAlgebra.openOrdered(consumer, row) : consumer.open(row)) {
			assertThat(row.encounterOrderRequired).isFalse();
			result = read(step, row, cursor);
		}
		assertThat(row.encounterOrderRequired).isFalse();
		return result;
	}

	private List<BindingSet> read(NativeRowsStep step, RowState row, RowCursor cursor) throws IOException {
		List<BindingSet> result = new ArrayList<>();
		while (cursor.next()) {
			MapBindingSet binding = new MapBindingSet();
			for (int index = 0; index < step.sourceSlots.length; index++) {
				int slot = step.sourceSlots[index];
				if ((row.boundMask() & (1L << slot)) != 0L) {
					binding.addBinding(step.targetNames[index], LmdbNativeValueCodec.toValue(
							row.decodedValue(slot, row.source.nativeValueCodec(), false)));
				}
			}
			result.add(binding);
			assertThat(row.encounterOrderRequired).isFalse();
		}
		return result;
	}

	private LmdbNativeEvaluationStrategy strategy(SailDataset dataset) {
		assertThat(dataset).isInstanceOf(NativeLmdbQuerySource.class);
		SailDatasetTripleTermSource source = new SailDatasetTripleTermSource(repository.getValueFactory(), dataset);
		LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(source, null, null, 0L,
				new EvaluationStatistics(), false);
		strategy.setQueryExecutionPolicy(store.getQueryExecutionPolicy());
		assertThat(strategy.getQueryExecutionPolicy()).isSameAs(store.getQueryExecutionPolicy());
		return strategy;
	}

	private static NativeRowsStep compile(TupleExpr root, LmdbNativeEvaluationStrategy strategy, SailDataset dataset) {
		LmdbNativeAggregateCompiler.CompileOutcome compiled = LmdbNativeAggregateCompiler.compileFinalTupleResult(
				QueryEvaluationUtility.pinFunctions(root), context(), strategy, (NativeLmdbQuerySource) dataset);
		assertThat(compiled.isSupported()).isTrue();
		assertThat(compiled.step()).isInstanceOf(NativeRowsStep.class);
		return (NativeRowsStep) compiled.step();
	}

	private static QueryEvaluationContext context() {
		return new QueryEvaluationContext.Minimal((Dataset) null);
	}

	private static List<BindingSet> drain(QueryEvaluationStep step) {
		try (CloseableIteration<BindingSet> result = step.evaluate(EmptyBindingSet.getInstance())) {
			return QueryResults.asList(result);
		}
	}

	private static final class Owned implements AutoCloseable {
		private final NativeRowsStep step;
		private final NativeLmdbQuerySource source;
		private final NativeExecutionContext owner;

		private Owned(NativeRowsStep step) {
			this.step = step;
			source = step.evaluationSource(EmptyBindingSet.getInstance());
			assertThat(source).isInstanceOf(SyntheticValueSource.class);
			assertThat(SyntheticValueSource.inheritedEvaluation(source)).isFalse();
			owner = ((SyntheticValueSource) source).executionContext();
			assertThat(owner).isNotNull();
			assertThat(owner.isClosed()).isFalse();
			NativeRowsStep.initializeQueryBase(source, EmptyBindingSet.getInstance());
		}

		private RowState row() {
			RowState row = new RowState(source, step.layout, EmptyBindingSet.getInstance(), step.originalExpr);
			assertThat(LmdbNativeAggregateCompiler.initializeRow(row, row.base, source, step.layout)).isTrue();
			return row;
		}

		@Override
		public void close() {
			owner.close();
		}
	}

